import sys

input = sys.stdin.read().split()
n = int(input[0])
m = int(input[1])
table = [[int(input[j * m + i + 2]) for i in range(m)] for j in range(n)]

row_spells = []
col_spells = []

for i in range(n):
    if sum(table[i]) < 0:
        row_spells.append(i + 1)
        for j in range(m):
            table[i][j] *= -1

for j in range(m):
    if sum(table[i][j] for i in range(n)) < 0:
        col_spells.append(j + 1)
        for i in range(n):
            table[i][j] *= -1

print(len(row_spells), ' '.join(map(str, row_spells)))
print(len(col_spells), ' '.join(map(str, col_spells)))
